function setReportCutoff(v){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(v)||!Number.isFinite(Date.parse(v+'T12:00:00Z'))||new Date(v+'T12:00:00Z').toISOString().slice(0,10)!==v)return;
 cutoff=v;lastRows={};window._neracaData=null;window._lrData=null;
 for(const id of ['dash-tahun','neraca-tahun','lr-tahun']){const el=document.getElementById(id);if(el){if(![...el.options].some(o=>o.value===v.slice(0,4)))el.add(new Option(v.slice(0,4),v.slice(0,4)));el.value=v.slice(0,4);}}
 updateCutoffTitles();refreshReports();
}
function updateCutoffTitles(){
 const label=cutoff.slice(8,10)+'/'+cutoff.slice(5,7)+'/'+cutoff.slice(0,4);
 for(const name of ['dashboard','neraca','labarugi'])if(PAGE_TITLES[name])PAGE_TITLES[name].sub='Cutoff '+label+' · '+version;
 const active=document.querySelector('.page.active')?.id?.replace('page-','');
 if(['dashboard','neraca','labarugi'].includes(active)){const el=document.getElementById('topbar-subtitle');if(el)el.textContent=PAGE_TITLES[active].sub;}
}
function refreshReports(){renderDashboard();const active=document.querySelector('.page.active')?.id;if(active==='page-neraca')renderNeraca();if(active==='page-labarugi')renderLabaRugi();if(active==='page-rekonsiliasi')renderRecon();if(active==='page-kas'){renderKasKu();renderKasSummaryKu();}}
window.financeFetchAll=async function(q){const rows=[];for(let offset=0;;offset+=500){const r=await q.range(offset,offset+499);if(r.error)throw r.error;rows.push(...(r.data||[]));if((r.data||[]).length<500)return rows;}};
const oldSaldo=getSaldoAkun;getSaldoAkun=function(k,y){if(Number(y)<2026)return oldSaldo(k,y);const c=D.coa.find(c=>c.kode===k);const v=ledger(y).balances.get(k)||0;return c?.jenis==='kredit'?-v:v;};
const oldProfit=hitungLabaBersih;hitungLabaBersih=function(y){return Number(y)>=2026?ledger(y).profit:oldProfit(y);};
const oldBS=renderNeraca,oldPL=renderLabaRugi,oldEN=exportNeraca,oldEL=exportLR;
renderNeraca=function(){const y=Number(document.getElementById('neraca-tahun').value);const group=document.getElementById('bs-compare-group');if(group)group.hidden=y>=2026;const b=document.getElementById('neraca-banding');if(b){b.disabled=y>=2026;b.title=y>=2026?'Perbandingan neraca tersedia pada Analisis Deviasi':'';}return y>=2026?renderBS(y):oldBS();};
renderLabaRugi=function(){const y=Number(document.getElementById('lr-tahun').value);const group=document.getElementById('lr-compare-group');if(group)group.hidden=y>=2026;const b=document.getElementById('lr-banding');if(b){b.disabled=y>=2026;b.title=y>=2026?'Pilih tahun2025 untuk membaca laporan historis; laporan2026 memakai jurnal yang diaudit':'';}return y>=2026?renderPL(y):oldPL();};
exportNeraca=function(){return Number(document.getElementById('neraca-tahun').value)>=2026?exportReport('neraca'):oldEN();};
exportLR=function(){return Number(document.getElementById('lr-tahun').value)>=2026?exportReport('labarugi'):oldEL();};
const oldDash=renderDashboard;renderDashboard=function(){const y=Number(document.getElementById('dash-tahun')?.value);if(y<2026)return oldDash();try{validData();const m=ledger(y);document.getElementById('dash-stats').innerHTML=[['Kas buku',m.cash],['Total aset',m.assets],['Ekuitas + laba',m.equity+m.profit],['Laba bersih',m.profit]].map(([n,v])=>`<div class="stat-card"><div class="stat-lbl">${n}</div><div class="stat-val" style="font-size:20px">${money(v)}</div><div class="stat-sub">Per ${esc(m.end)}</div></div>`).join('');document.getElementById('dash-neraca').innerHTML=tbl(['Neraca sementara','Rupiah'],[['Aset',money(m.assets)],['Kewajiban',money(m.liabilities)],['Ekuitas + laba',money(m.equity+m.profit)],['Selisih jurnal',money(m.difference)]]);document.getElementById('dash-lr').innerHTML=tbl(['Usaha / alokasi','Laba'],Object.entries(m.units).map(([n,v])=>[esc(n),money(v)]));document.getElementById('dash-aset').innerHTML='<p>Aset menurut jurnal: '+money(m.accounts.filter(c=>c.kelompok==='aktiva_tetap').reduce((s,c)=>s+c.saldo,0))+'</p><p>Renovasi PW4 belum siap dipakai; masih aset dalam pengerjaan, belum disusutkan. Buka Rekonsiliasi Kas untuk kecocokan uang aktual.</p>';}catch(e){document.getElementById('dash-stats').textContent=e.message;}};
const oldDev=renderDeviasi;renderDeviasi=function(){const y1=Number(document.getElementById('dev-t1').value),y2=Number(document.getElementById('dev-t2').value);if(y1<2026&&y2<2026)return oldDev();const m1=ledger(y1),m2=ledger(y2);document.getElementById('deviasi-content').innerHTML='<div class="card"><h3>Perbandingan neraca menurut jurnal</h3><p>2025 memakai saldo pembuka resmi akhir tahun, termasuk laba 2025. Tahun 2026 sampai '+esc(ledger(2026).end)+'. Periode tidak sama panjang.</p>'+tbl(['Pos',String(y1),String(y2),'Selisih'],[['Kas',m1.cash,m2.cash],['Aset',m1.assets,m2.assets],['Kewajiban',m1.liabilities,m2.liabilities],['Ekuitas tanpa tambahan laba',m1.equity,m2.equity]].map(([n,a,b])=>[n,money(a),money(b),money(a-b)]))+'</div>';};
