const oldCode=getFnKodeCOA;getFnKodeCOA=function(id){return Number(id)===3?'1-106':oldCode(id);};
const oldBB=renderBukuBesar,oldEBB=exportBukuBesar;let auditedBook=null;
function buildBook(){const month=document.getElementById('bb-bulan')?.value||'',id=Number(document.getElementById('bb-akun')?.value);if(month&&Number(month.slice(0,4))<2026)return null;const c=D.coa.find(c=>c.id===id);if(!c)return null;const y=month?Number(month.slice(0,4)):Number(cutoff.slice(0,4)),end=month?[new Date(y,Number(month.slice(5)),0).toLocaleDateString('sv-SE'),selectedDate(y)].sort()[0]:selectedDate(y);const h=new Map(D.jurnal_umum.filter(j=>j.status==='posted'&&j.tanggal<=end&&(j.referensi==='NERACA-2025'||j.tanggal>='2026-01-01')).map(j=>[j.id,j]));let balance=0,opening=0;const all=D.jurnal_detail.filter(d=>d.coa_id===id&&h.has(d.jurnal_id)).slice().sort((a,b)=>h.get(a.jurnal_id).tanggal.localeCompare(h.get(b.jurnal_id).tanggal)||a.jurnal_id-b.jurnal_id||num(a.id)-num(b.id));const rows=[];for(const d of all){const j=h.get(d.jurnal_id);balance+=(c.jenis==='kredit'?-1:1)*(num(d.debit)-num(d.kredit));if(month&&!j.tanggal.startsWith(month)){opening=balance;continue;}rows.push([j.tanggal,j.no_jurnal||String(j.id),j.keterangan||'',num(d.debit),num(d.kredit),balance]);}return {name:c.kode+' '+c.nama,end,opening,rows};}
renderBukuBesar=function(){const m=buildBook();auditedBook=m;if(!m)return oldBB();document.getElementById('bb-content').innerHTML='<p>Buku besar jurnal posted, saldo awal resmi dan koreksi. Per '+esc(m.end)+'</p><h3>'+esc(m.name)+'</h3>'+tbl(['Tanggal','Jurnal','Keterangan','Debit','Kredit','Saldo'],[['Saldo sebelum periode','','','','',money(m.opening)],...m.rows.map(r=>r.map((v,i)=>i>=3?money(v):esc(v)))]);};
exportBukuBesar=function(){if(!auditedBook)return oldEBB();const m=auditedBook,ws=XLSX.utils.aoa_to_sheet([['Buku besar',m.name],['Per',m.end],['Saldo sebelum periode',m.opening],['Tanggal','Jurnal','Keterangan','Debit','Kredit','Saldo'],...m.rows]);ws['!cols']=[{wch:14},{wch:20},{wch:65},{wch:20},{wch:20},{wch:20}];for(const c of Object.values(ws))if(c&&typeof c.v==='number')c.z='#,##0;(#,##0);"-"';const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Buku Besar');XLSX.writeFile(wb,'UBNB_Buku_Besar_'+m.end+'.xlsx');};
const oldSummary=renderKasSummaryKu;renderKasSummaryKu=function(){oldSummary();const el=document.getElementById('kas-summary');if(el)el.insertAdjacentHTML('beforeend','<p>Saldo di sini adalah pembukuan. <button class="btn secondary sm" onclick="showPage(\'rekonsiliasi\')">Cocokkan uang aktual</button></p>');};
recalcAllSaldo=function(){const y=Number(today().slice(0,4));const rows=D.kas.filter(k=>num(k.saldo)!==0).map(k=>[k,num(k.saldo)-getSaldoAkun(getFnKodeCOA(k.id),y)]);const bad=rows.filter(([k,d])=>Math.abs(d)>0.01);toast(bad.length?bad.length+' kas berbeda dari jurnal. Buka Rekonsiliasi Kas; saldo belum diubah.':'Saldo kas dan jurnal cocok; tidak ada saldo diubah.',!!bad.length);renderKasKu();};
const oldRefresh=refreshAll;refreshAll=async function(){await oldRefresh();refreshReports();};
const oldShow=showPage;showPage=function(n,el){oldShow(n,el);if(n==='rekonsiliasi')loadRecon();};
function reconDate(){return document.getElementById('recon-date').value||today();}
async function loadRecon(){reconLoaded=false;reconError='';try{if(!CU)throw Error('Masuk terlebih dahulu');const allowed=await sb.rpc('ubnb_finance_recon_allowed');if(allowed.error)throw allowed.error;if(!allowed.data)throw Error('Rekonsiliasi tersedia untuk pemilik/admin/bendahara/keuangan.');recon=await financeFetchAll(sb.from('keuangan_rekonsiliasi').select('*').or(`and(jenis.eq.aktual,tanggal.eq.${reconDate()}),and(jenis.eq.bukti,tanggal.lte.${reconDate()}))`).eq('diarsipkan',false).order('id'));reconLoaded=true;}catch(e){reconError=e.message;}renderRecon();}
function actualRows(){return recon.filter(r=>r.jenis==='aktual');}
function matches(b){const rows=(D.kas_mutasi||[]).filter(m=>m.tipe==='keluar'&&num(m.jumlah)===num(b.jumlah)&&(!b.kas_id||m.kas_id===b.kas_id));return rows.sort((a,c)=>Math.abs(Date.parse(a.tanggal)-Date.parse(b.tanggal))-Math.abs(Date.parse(c.tanggal)-Date.parse(b.tanggal))).slice(0,15);}
let evidenceFilter='pending';
function isMatched(b){const m=(D.kas_mutasi||[]).find(m=>m.id===b.mutasi_id);return !!(m&&m.tipe==='keluar'&&num(m.jumlah)===num(b.jumlah)&&(!b.kas_id||m.kas_id===b.kas_id));}
function renderRecon(){
 const out=document.getElementById('recon-result');if(!out)return;
 if(!reconLoaded){out.innerHTML='<p>'+esc(reconError||'Memuat rekonsiliasi…')+'</p>';return;}
 const m=ledger(Number(reconDate().slice(0,4)),reconDate()),actual=actualRows(),known=actual.reduce((s,r)=>s+num(r.jumlah),0),pending=actual.filter(r=>r.jumlah===null||!r.terkonfirmasi);
 document.getElementById('recon-book-date').textContent='Saldo buku per '+m.end+' · Piutang tidak dihitung sebagai kas.';
 const note=r=>r.catatan?'<details class="rek-note"><summary>Catatan</summary><p>'+esc(r.catatan)+'</p></details>':'';
 const status=r=>'<span class="rek-badge '+(r.terkonfirmasi?'ok':'wait')+'">'+(r.terkonfirmasi?'Dikonfirmasi':'Belum dikonfirmasi')+'</span>';
 const amount=r=>r.jumlah===null?'Belum diketahui':money(r.jumlah);
 const label=r=>esc(r.label==='Rekening pada baris pertama foto'?'Rekening 1 (nama perlu dipastikan)':r.label);
 out.innerHTML='<div class="rek-summary">'+[['Kas buku',m.cash],['Uang teridentifikasi',known],['Selisih sementara',m.cash-known]].map(([n,v])=>'<div><span>'+n+'</span><strong>'+money(v)+'</strong></div>').join('')+'</div><p class="rek-notice">'+(actual.length?(pending.length?pending.length+' lokasi belum dikonfirmasi lengkap.':'Semua lokasi yang dicatat sudah dikonfirmasi.'):'Belum ada posisi aktual.')+' Selisih masih perlu ditelusuri.</p><h3>Posisi uang</h3>';
 out.innerHTML+='<div class="rek-desktop">'+tbl(['Rekening / pemegang','Nominal','Status / tindakan'],actual.map(r=>[label(r)+note(r),amount(r),status(r)+' <button class="btn secondary sm" onclick="FinanceAudit.edit('+r.id+')">Edit</button>']))+'</div>';
 out.innerHTML+='<div class="rek-mobile">'+actual.map(r=>'<article class="rek-position"><div class="rek-row"><strong>'+label(r)+'</strong><b class="rek-money">'+amount(r)+'</b></div><div class="rek-row">'+status(r)+'<button class="btn secondary sm" onclick="FinanceAudit.edit('+r.id+')">Edit</button></div>'+note(r)+'</article>').join('')+'</div>';
 const evidence=recon.filter(r=>r.jenis==='bukti'),matched=evidence.filter(isMatched),unmatched=evidence.length-matched.length;
 out.innerHTML+='<div class="rek-section"><h3>Bukti pengeluaran</h3><button class="btn secondary sm no-print" onclick="FinanceAudit.newEvidence()">+ Tambah bukti</button></div><p class="rek-meta">Cocokkan tanggal, penerima, dan keperluan. Nominal sama belum tentu transaksi yang sama.</p><div class="rek-tabs no-print">'+[['pending','Perlu diperiksa',unmatched],['matched','Sudah cocok',matched.length],['all','Semua',evidence.length]].map(([v,n,c])=>'<button class="'+(evidenceFilter===v?'selected':'')+'" onclick="FinanceAudit.filter(\''+v+'\')">'+n+' ('+c+')</button>').join('')+'</div>';
 const shown=evidence.filter(b=>evidenceFilter==='all'||(evidenceFilter==='matched'?isMatched(b):!isMatched(b)));
 out.innerHTML+=shown.length?shown.map(b=>{
  const ok=isMatched(b),opts=matches(b).map(x=>'<option value="'+x.id+'">#'+x.id+' · '+esc(x.tanggal)+' · '+esc(x.keterangan)+'</option>').join('');
  return '<article class="rek-evidence"><div class="rek-row"><div><small>'+esc(b.tanggal)+'</small><h4>'+esc(b.label.split(';')[0])+'</h4></div><strong class="rek-money">'+money(b.jumlah)+'</strong></div><span class="rek-badge '+(ok?'ok':'wait')+'">'+(ok?'Sudah cocok · Mutasi #'+b.mutasi_id:b.mutasi_id?'Pasangan berubah; periksa':opts?'Ada calon pasangan':'Belum ditemukan pasangan')+'</span><details class="rek-note"'+(!ok?' open':'')+'><summary>Rincian dan tindakan</summary><p>'+esc(b.label)+'</p>'+(b.catatan?'<p>'+esc(b.catatan)+'</p>':'')+(b.bukti_url?'<p><a target="_blank" rel="noopener" href="'+esc(b.bukti_url)+'">Lihat bukti</a></p>':'')+'<div class="rek-actions no-print">'+(!ok?'<select id="match-'+b.id+'"><option value="">Pilih mutasi keluar</option>'+opts+'</select><button class="btn secondary sm" onclick="FinanceAudit.match('+b.id+')">Tautkan</button>':'')+(b.mutasi_id?'<button class="btn secondary sm" onclick="FinanceAudit.unlink('+b.id+')">Lepas pasangan</button>':'')+'<button class="btn secondary sm" onclick="FinanceAudit.edit('+b.id+')">Edit bukti</button></div></details></article>';
 }).join(''):'<p class="rek-empty">'+(evidenceFilter==='pending'?'Semua bukti yang sudah dimasukkan telah cocok. Tambahkan bukti lain untuk memeriksa pengeluaran yang belum dicatat.':'Belum ada bukti pada kelompok ini.')+'</p>';
 out.innerHTML+='<details class="rek-note"><summary>Audit yang masih perlu diselesaikan</summary><ul><li>Laporan kas Akbar dan penelusuran sisa selisih kas. Rekening BMT RA sudah dipetakan sebagai lokasi Kas Utama.</li><li>Piutang, utang supplier, serta bukti pelunasan.</li><li>Persediaan akhir diterima untuk laporan sementara. Renovasi belum siap dipakai dan dicatat sebagai aset dalam pengerjaan.</li><li>Ringkasan SHU, dasar ekuitas transisi BMT, dan bukti penyelesaian setoran laundry.</li></ul></details>';
}
function formHtml(){return `<div class="card no-print"><h3>Catat lokasi uang atau bukti pembayaran</h3><input type="hidden" id="recon-id"><div class="form-grid"><div class="irow"><label>Tanggal posisi / bukti</label><input type="date" id="recon-item-date" value="${today()}"></div><div class="irow"><label>Jenis</label><select id="recon-kind"><option value="aktual">Posisi uang aktual</option><option value="bukti">Bukti pengeluaran</option></select></div><div class="irow"><label>Rekening / pemegang / keperluan</label><input id="recon-label" maxlength="200"></div><div class="irow"><label>Nominal (kosong = belum diketahui)</label><input type="number" min="0" step="0.01" id="recon-amount"></div><div class="irow"><label>Kas sumber bukti (opsional)</label><select id="recon-kas"><option value="">Semua kas</option></select></div><div class="irow"><label>Catatan / penerima</label><input id="recon-note"></div><div class="irow"><label>Link bukti https (opsional)</label><input type="url" id="recon-url"></div></div><label><input type="checkbox" id="recon-confirm"> Nominal posisi uang sudah dikonfirmasi</label><p><button class="btn primary" onclick="FinanceAudit.save(this)">Simpan catatan</button> <button class="btn secondary" onclick="FinanceAudit.reset()">Bersihkan</button></p><p>Posisi uang ditampilkan untuk tanggal pemeriksaan. Bukti pengeluaran ditampilkan sampai tanggal pemeriksaan. Simpan setiap bukti dengan tanggal pembayarannya. Menyimpan di sini tidak mengubah kas atau jurnal.</p></div>`;}
async function persist(row){const {id,...values}=row;const response=id?await sb.from('keuangan_rekonsiliasi').update(values).eq('id',id).select('id'):await sb.from('keuangan_rekonsiliasi').upsert(values,{onConflict:'jenis,tanggal,label'}).select('id');if(response.error)throw response.error;if(!response.data?.length)throw Error('Catatan tidak tersimpan. Periksa akses/sesi.');}
function reset(){document.getElementById('recon-item-date').value=reconDate();for(const id of ['recon-id','recon-label','recon-amount','recon-note','recon-url'])document.getElementById(id).value='';document.getElementById('recon-confirm').checked=false;document.getElementById('recon-kind').disabled=false;}
function edit(id){document.getElementById('recon-form').open=true;const r=recon.find(r=>r.id===id);if(!r)return;document.getElementById('recon-item-date').value=r.tanggal;document.getElementById('recon-id').value=r.id;document.getElementById('recon-kind').value=r.jenis;document.getElementById('recon-kind').disabled=true;document.getElementById('recon-label').value=r.label;document.getElementById('recon-amount').value=r.jumlah??'';document.getElementById('recon-note').value=r.catatan;document.getElementById('recon-url').value=r.bukti_url;document.getElementById('recon-kas').value=r.kas_id||'';document.getElementById('recon-confirm').checked=r.terkonfirmasi;document.getElementById('recon-label').scrollIntoView({block:'center'});}
async function save(btn){btn.disabled=true;try{const id=Number(document.getElementById('recon-id').value)||null,kind=document.getElementById('recon-kind').value,label=document.getElementById('recon-label').value.trim(),val=document.getElementById('recon-amount').value,amount=val===''?null:Number(val),url=document.getElementById('recon-url').value.trim();if(!label||amount!==null&&(!Number.isFinite(amount)||amount<0)||kind==='bukti'&&!(amount>0))throw Error('Isi keperluan dan nominal yang benar.');if(url&&!/^https:\/\//i.test(url))throw Error('Link bukti harus https.');const row={jenis:kind,tanggal:document.getElementById('recon-item-date').value||reconDate(),label,jumlah:amount,terkonfirmasi:document.getElementById('recon-confirm').checked,kas_id:Number(document.getElementById('recon-kas').value)||null,catatan:document.getElementById('recon-note').value.trim(),bukti_url:url};if(id)row.id=id;await persist(row);reset();await loadRecon();toast('Catatan tersimpan; kas dan jurnal tidak diubah');}catch(e){toast(e.message,true);}finally{btn.disabled=false;}}
async function link(id,remove=false){try{const row=recon.find(r=>r.id===id);if(!row)throw Error('Bukti tidak ditemukan');const mid=remove?null:Number(document.getElementById('match-'+id).value);if(!remove&&!mid)throw Error('Pilih mutasi keluar');await persist({id,mutasi_id:mid});await loadRecon();}catch(e){toast(e.message,true);}}
function exportRecon(){if(!reconLoaded||!window.XLSX)return toast('Muat data dulu',true);const rows=[['Rekonsiliasi kas UBNB',reconDate()],['Jenis','Tanggal','Label','Nominal','Terkonfirmasi','Mutasi ID','Catatan','Link bukti','Dicatat oleh'],...recon.map(r=>[r.jenis,r.tanggal,r.label,r.jumlah,r.terkonfirmasi?'Ya':'Belum',r.mutasi_id,r.catatan,r.bukti_url,r.updated_by])];const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=[{wch:12},{wch:13},{wch:40},{wch:20},{wch:16},{wch:14},{wch:60},{wch:35},{wch:20}];const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Rekonsiliasi');XLSX.writeFile(wb,'UBNB_Rekonsiliasi_'+reconDate()+'.xlsx');}
